/**
 * Static index of every Google Font (~1900 families). Generated by
 * `scripts/generate-google-fonts-list.mjs` from Google's live font
 * metadata. Re-run that script to pick up newly-published fonts.
 *
 * Bundled inline so the theme controller has zero network dependency
 * at addon-init time. Only loaded inside the Storybook manager iframe.
 */
import raw from "./google-fonts.json";

export interface GoogleFontEntry {
  /** Family name as Google publishes it, e.g. "Roboto Mono". */
  family: string;
  /** Google's category tag: "Sans Serif", "Serif", "Display", "Handwriting", "Monospace". */
  category: string;
  /** Numeric weights the family ships with (e.g. [300, 400, 700]). */
  weights: number[];
  /** Whether the family ships italic variants. */
  italic: boolean;
  /** Whether the family is a variable font. */
  variable: boolean;
  /** Google's popularity rank (1 = most popular). */
  popularity: number;
}

export const GOOGLE_FONTS = raw as GoogleFontEntry[];

/** Subset Google calls "monospace" — handy default pool for the code font picker. */
export const MONOSPACE_FONTS = GOOGLE_FONTS.filter(
  (f) => f.category === "Monospace"
);

/**
 * Look up a font by family name. The picker stores `theme.fontFamily`
 * as a quoted string (e.g. `"Roboto", sans-serif`), so the lookup
 * accepts either the bare family or the quoted form.
 */
export function findFont(query: string): GoogleFontEntry | undefined {
  const cleaned = query.replace(/^["']|["'].*$/g, "").trim();
  return GOOGLE_FONTS.find(
    (f) => f.family.toLowerCase() === cleaned.toLowerCase()
  );
}
